// If pi-ai ever forwards the original Error (or a fetch/dispatcher hook that lets
// us capture the cause ourselves), classify on `code`/`cause` instead of text.
function classifyPiAiError(message: string): string {
  if (hasStatus(message, '401|403')) return 'AUTH'
  if (isQuotaExceededError(message)) return QUOTA_EXCEEDED_CODE
  // Gateways such as OmniRoute report a brief credential cooldown without a
  // status code: `All credentials for model … are cooling down (reset after 5s)`.
  if (hasStatus(message, '429') || /rate.?limit|cooling down/i.test(message)) return 'RATE_LIMIT'
  // A rejected request body (gateway or provider size cap): resending the
  // same request cannot succeed, so it is invalid, not transient.
  if (hasStatus(message, '413') || /failed to buffer the request body:\s*length limit exceeded|payload too large|request body too large/i.test(message)) return 'INVALID_REQUEST'
  if (hasStatus(message, '400') || /invalid.?request/i.test(message)) return 'INVALID_REQUEST'
  if (hasStatus(message, '5\\d\\d')) return 'SERVER'

  return 'PI_AI_ERROR'
}

// A status code stands alone. Digits after `:` or `.` belong to an address or
// version: OmniRoute reports a `[502]: fetch failed` whose cause lists IPv6
// addresses such as `2001:4860:4844:400::`, and that 400 is not the status.
function hasStatus(message: string, codes: string): boolean {
  return new RegExp(`(?<![\\w.:])(?:${codes})\\b`).test(message)
}

